function perfectpixel_idle_logout_seconds() {
	return max( 1, (int) '{{idle_logout_minutes}}' ) * MINUTE_IN_SECONDS;
}

// Server side: log out if the last request is too old, otherwise record this one (at most once a minute).
function perfectpixel_idle_logout_check() {
	if ( ! is_user_logged_in() || wp_doing_cron() || ( wp_doing_ajax() && isset( $_POST['action'] ) && 'heartbeat' === $_POST['action'] ) ) {
		return;
	}
	$user_id = get_current_user_id();
	$last    = (int) get_user_meta( $user_id, 'perfectpixel_last_activity', true );
	if ( $last && time() - $last > perfectpixel_idle_logout_seconds() ) {
		delete_user_meta( $user_id, 'perfectpixel_last_activity' );
		wp_logout();
		if ( ! wp_doing_ajax() ) {
			wp_safe_redirect( wp_login_url() );
			exit;
		}
		return;
	}
	if ( time() - $last > MINUTE_IN_SECONDS ) {
		update_user_meta( $user_id, 'perfectpixel_last_activity', time() );
	}
}

// Browser side: log out an open tab after the idle time.
function perfectpixel_idle_logout_script() {
	if ( ! is_user_logged_in() ) {
		return;
	}
	?>
	<script>
	( function ( ms, url ) {
		var timer;
		var reset = function () {
			clearTimeout( timer );
			timer = setTimeout( function () { window.location.href = url; }, ms );
		};
		[ 'mousemove', 'keydown', 'click', 'scroll', 'touchstart' ].forEach( function ( ev ) {
			document.addEventListener( ev, reset, { passive: true } );
		} );
		reset();
	} )( <?php echo (int) perfectpixel_idle_logout_seconds() * 1000; ?>, <?php echo wp_json_encode( html_entity_decode( wp_logout_url( wp_login_url() ) ) ); ?> );
	</script>
	<?php
}
